def determine_winner(n, k, cards):
    count = sum(1 for card in cards if card == '1')

    if (count % 2 == 0 and k % 2 == 0) or (count % 2 != 0 and k % 2 != 0):
        return "tokitsukaze"
    else:
        return "quailty"

